export const DASHBOARD_ALLOWED_NEXT_PATHS = [
    '/api/slack/connect',
    '/api/end-user-auth/deployment',
    '/api/cli/oauth/authorize',
    '/api/admin-mcp/oauth/authorize',
    '/api/bitbucket-oauth/callback',
    '/slack/connect',
];
const EDITOR_NEXT_PATH_PATTERN = /^\/[^/?#]+\/[^/?#]+(?:\/~\/[^?#]+|\/editor\/[^/?#]+(?:\/~\/[^?#]+)?)?$/;
export const validateDashboardRedirect = (next) => {
    if (DASHBOARD_ALLOWED_NEXT_PATHS.some((val) => next.startsWith(val)))
        return true;
    try {
        const baseUrl = 'https://example.com';
        const url = new URL(next, baseUrl);
        const normalizedNext = `${url.pathname}${url.search}${url.hash}`;
        return (url.origin === baseUrl &&
            normalizedNext === next &&
            EDITOR_NEXT_PATH_PATTERN.test(url.pathname));
    }
    catch (_a) {
        return false;
    }
};
